      pistola: { start: "pistola-inicio", fx: "manos-arriba", speak: tx("¿Te rindes fácil?", "¿Cuándo alguien te confundió con una autoridad?", "¿Qué consecuencias tiene fingir un poder que no tienes?") },
      granada: { start: "granada-inicio", fx: "huye", speak: tx("¿Haces bromas con cosas peligrosas?", "¿Qué caos aprovechaste alguna vez para escapar de algo?", "¿Por qué el pánico ajeno puede ser una oportunidad, y es justo usarla?") },
      gas: { start: "gas-inicio", fx: "defensa", speak: tx("¿Tus vecinos tienen miedo de noche?", "¿Qué medidas de seguridad toman en tu barrio?", "¿Cuándo la desconfianza entre vecinos empieza a hacer más daño que el peligro?") },
      lapiz: { start: "lapiz-inicio", fx: "curioso", speak: tx("¿Escribes notas a tu familia?", "¿Qué nota escribiste para pedir perdón a alguien?", "¿Qué se puede decir en una nota que no se puede decir en persona?") },
      libro: { start: "libro-inicio", fx: "risa", speak: tx("¿Lees en la calle?", "¿Qué excusa usaste alguna vez para ayudar a alguien?", "¿Por qué un libro abierto hace que una persona parezca inofensiva?") },
      corazon: { start: "corazon-inicio", fx: "abrazo", speak: tx("¿Quién te escucha cuando estás mal?", "¿Cómo consolarías a alguien que su familia no quiere escuchar?", "¿Qué hace falta para que un barrio vuelva a confiar en alguien?") },
